def run(args,data=None):
 r=subprocess.run(args,input=data,text=True,capture_output=True,timeout=45)
 if r.returncode:raise RuntimeError('Falló '+P(args[0]).name+'; salida omitida para proteger datos.')
 return r.stdout.strip()
def sha(data):return hashlib.sha256(data).hexdigest()
def check(ok,label):
 if not ok:raise RuntimeError(label)
 print('OK: '+label)
def safe(path):
 for part in [path,*path.parents]:
  if part.is_symlink():raise RuntimeError('Enlace no permitido en destino conocido.')
 return path
def attrs(path):
 s=safe(path).stat();return [stat.S_IMODE(s.st_mode),s.st_uid,s.st_gid]
def atomic(path,data,attributes):
 safe(path);fd,tmp=tempfile.mkstemp(prefix='.uiat-camera-',dir=path.parent)
 try:
  with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
  os.chmod(tmp,attributes[0]);os.chown(tmp,attributes[1],attributes[2]);os.replace(tmp,path)
 finally:
  if os.path.exists(tmp):os.unlink(tmp)
def directory(path,attributes):
 safe(path);path.mkdir();os.chmod(path,attributes[0]);os.chown(path,attributes[1],attributes[2])
def sql(query):return run(['mariadb','--batch','--skip-column-names'],query)
def rows(query):
 out=sql(query);return [line.split('\t') for line in out.splitlines()] if out else []
def permissions(expected_grants=None):
 if expected_grants is None:expected_grants=GRANTS
 g="CONCAT(CHAR(39),'uiat_chatgpt_reader',CHAR(39),'@',CHAR(39),'localhost',CHAR(39))"
 check(all(row==['USAGE','NO'] for row in rows('SELECT PRIVILEGE_TYPE,IS_GRANTABLE FROM information_schema.USER_PRIVILEGES WHERE GRANTEE='+g+';')),'sin permisos globales ni GRANT OPTION')
 for scope in ['SCHEMA','TABLE']:
  check(not rows('SELECT PRIVILEGE_TYPE FROM information_schema.'+scope+'_PRIVILEGES WHERE GRANTEE='+g+';'),'sin permisos amplios de '+scope.lower())
 for table in ['roles_mapping','procs_priv','proxies_priv']:
  check(sql("SELECT COUNT(*) FROM mysql."+table+" WHERE User='uiat_chatgpt_reader';")=='0','sin privilegios adicionales en '+table)
 check(rows("SELECT Host FROM mysql.user WHERE User='uiat_chatgpt_reader';")==[['localhost']],'cuenta dedicada limitada a localhost')
 expected={('uiatnorte',table,column,'SELECT','NO') for table,columns in expected_grants.items() for column in columns}
 actual=rows('SELECT TABLE_SCHEMA,TABLE_NAME,COLUMN_NAME,PRIVILEGE_TYPE,IS_GRANTABLE FROM information_schema.COLUMN_PRIVILEGES WHERE GRANTEE='+g+';')
 check(set(map(tuple,actual))==expected,'SELECT exclusivamente en '+str(sum(map(len,expected_grants.values())))+' columnas previstas')
def request(path,payload=None):
 args=['curl','--silent','--show-error','--max-time','15','--max-redirs','0','--resolve',HOST+':443:127.0.0.1','--write-out','\nUIAT_HTTP_STATUS:%{http_code}'];body=None
 if payload is not None:args+=['--header','Content-Type: application/json','--header','Accept: application/json, text/event-stream','--data-binary','@-'];body=json.dumps(payload)
 result=run(args+['https://'+HOST+path],body);text,code=result.rsplit('UIAT_HTTP_STATUS:',1);return int(code),text.removesuffix('\n')
def rpc(method,params=None):return request('/mcp-uiat',{'jsonrpc':'2.0','id':1,'method':method,'params':params or {}})
def tools(expected):
 for attempt in range(4):
  code,text=rpc('tools/list');data=json.loads(text)
  result=data.get('result',{}).get('tools',[])
  if code==200 and {t.get('name') for t in result}==expected:break
  if attempt<3:time.sleep(1)
 check(code==200 and {t.get('name') for t in result}==expected,'herramientas anunciadas coinciden con la versión prevista')
 if FEATURE in expected:
  t=next(t for t in result if t['name']==FEATURE)
  check(t.get('annotations')=={'readOnlyHint':False,'destructiveHint':False,'idempotentHint':False,'openWorldHint':False},'creación temporal declarada sin efectos sobre registros de negocio')
 code,text=rpc('tools/call',{'name':FEATURE if FEATURE in expected else 'consultar_expediente','arguments':{}})
 check(code==401 and json.loads(text)=={'error':'Autenticación requerida.'},'consulta anónima rechazada sin datos ni documentos')
def web_status():
 expected={'/login.php':200,'/.env':403,'/.env.save':403,'/.env.local':403}
 for path,code in expected.items():check(request(path)[0]==code,path+': protección/disponibilidad conservada')
 return {p:request(p)[0] for p in ['/mcp-demo','/api/v1/buscar_expedientes.php']}
def logs_private():
 check(sha(LOGCONF.read_bytes())==LOG_SHA,'formato de logs excluye consulta, Cookie, Authorization y Referer')
 for filename in ['uiatnorte.conf','uiatnorte-le-ssl.conf']:
  text=(SITES/filename).read_text()
  check(re.findall(r'^\s*CustomLog\s+\S+\s+(\S+)',text,re.M|re.I)==['uiat_privado'],'logs privados en '+filename)
 check(str(CONF) in (SITES/'uiatnorte-le-ssl.conf').read_text(),'configuración limitada al virtualhost HTTPS de UIAT')
def code_integrity(mapping):
 www=pwd.getpwnam('www-data')
 check(attrs(RELEASE)==[0o750,0,www.pw_gid],'fuentes en directorio root:www-data 0750')
 for rel,digest in mapping.items():
  p=RELEASE/rel
  if attrs(p)!=[0o640,0,www.pw_gid] or not p.is_file() or sha(p.read_bytes())!=digest:raise RuntimeError('Integridad o permisos distintos en fuente: '+rel)
 check(True,'fuentes y dependencias verificadas por SHA-256')
def private_permissions():
 www=pwd.getpwnam('www-data')
 check(attrs(PRIVATE)==[0o750,0,www.pw_gid],'directorio de configuración privado')
 for name in ['settings.json','factory.php','private.pem','public.pem']:check(attrs(PRIVATE/name)==[0o640,0,www.pw_gid],'permisos privados: '+name)
 check(attrs(RUNTIME)==[0o700,www.pw_uid,www.pw_gid],'estado y auditoría privados')
 for name in ['oauth.sqlite','audit.jsonl']:check(attrs(RUNTIME/name)==[0o600,www.pw_uid,www.pw_gid],'permisos conservados: '+name)
def load_package():
 package=P(__file__).resolve().parent/'uiat-necropsia-fiel-candidato-v6.tar.gz'
 check(sha(package.read_bytes())==PACKAGE_SHA,'paquete de necropsia verificado por SHA-256')
 contents={}
 with tarfile.open(package) as archive:
  for member in archive.getmembers():
   if not member.isfile() or member.name not in CANDIDATE or member.name in contents:raise RuntimeError('Paquete candidato inesperado.')
   value=archive.extractfile(member).read()
   if sha(value)!=CANDIDATE[member.name]:raise RuntimeError('Integridad interna del candidato no válida.')
   contents[member.name]=value
 check(set(contents)==set(CANDIDATE),'paquete completo y sin rutas adicionales')
 return contents

